import{z as l,x as B,o as E,c as d,q as o,j as p,D as t,d as r,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"两阶段提交","description":"","frontmatter":{"title":"两阶段提交","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/two-pc.md","filePath":"cs/two-pc.md","lastUpdated":1791063341000}'),A={name:"cs/two-pc.md"};function m(C,a,D,c,P,h){const s=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="两阶段提交" tabindex="-1">两阶段提交 <a class="header-anchor" href="#两阶段提交" aria-label="Permalink to &quot;两阶段提交&quot;">​</a></h1><div class="epigraph"><p>先投票再决策：所有参与者同意才提交，否则全体撤；协调器的日志是分布式原子的支点。</p><footer>—— 据 Lampson and Sturgis；Gray, Notes on Database Operating Systems；Bernstein 对 2PC 的整理</footer></div><p><a href="/cs/wait-die">上一课</a>处理单库等待图。本课不重画环。缺口是：一次事务改了两个资源管理器（两库、库与消息队列），本地 ARIES 只能保证各自 A/D，不能保证<strong>一起</strong>提交或一起撤。两阶段提交（2PC）加一个协调器：准备阶段锁住并记下「可提交」，提交阶段统一决策。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>本地 commit 记录一刷盘，该节点已持久。若另一节点随后 abort，原子性跨节点失败。缺口不是再讲 WAL，而是协议：协调器收集 yes/no；全 yes 则发 commit，否则 abort。参与者在 prepared 状态必须等待决策，即使自己已经把 UNDO 信息钉在日志里——这是阻塞窗口，不是算法写错。</p><p><span class="marginnote">假设故障：宕机、丢消息，不是拜占庭。协调器自身崩溃必须靠其日志恢复决策，否则参与者永远 prepared。三阶段提交减阻塞，主干不替换 2PC 作为第一协议。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>阶段一：协调器写 prepare，问参与者。参与者若能保证以后既可 commit 也可 abort，则写 prepared 日志并答 yes。阶段二：协调器写全局 commit/abort 并通知。参与者按决策 REDO 或 UNDO，释放锁。本课不把 XA 接口细节当理论，只锁定这两次持久决策点。</p>',8)),(E(),p(i,null,{default:t(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%8D%8F%E8%B0%83%E5%99%A8%22%5D%20--%3E%20P%5B%22prepare%22%5D%0A%20%20P%20--%3E%20V%5B%22yes%20%2F%20no%22%5D%0A%20%20V%20--%3E%7C%22%E5%85%A8%20yes%22%7C%20COM%5B%22%E5%85%A8%E5%B1%80%20commit%22%5D%0A%20%20V%20--%3E%7C%22%E4%BB%BB%E4%B8%80%20no%22%7C%20AB%5B%22%E5%85%A8%E5%B1%80%20abort%22%5D%0A%20%20COM%20--%3E%20CIA%5B%22%E5%90%8E%E8%AF%BE%3A%20CIA%20%E4%B8%89%E5%85%83%E7%BB%84%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("2PC 给的是崩溃故障下的原子性，不是隔离：各节点内部仍用 2PL/MVCC。prepared 期间锁不放，跨节点死锁与阻塞会放大上一课的等待图。协调器日志丢失且未复制，会出现「不知道该提交还是撤」的启发式窗口——工程上靠复制协调器或人工。本课与"),e("a",{href:"/cs/tcp-handshake"},"网络"),r("的可靠字节流不同：这里要的是全体一致的提交位，不是一条连接的字节序。")],-1)),a[5]||(a[5]=e("p",null,"阶段一结束时参与者必须既能提交也能撤，所以 UNDO 信息与锁都还在。",-1)),a[6]||(a[6]=e("p",null,"阻塞窗口正是从协调器的单点故障长出来的：",-1)),(E(),p(i,null,{default:t(()=>[n(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%8F%82%E4%B8%8E%E8%80%85%E5%B7%B2%E5%9B%9E%20yes%2C%20%E8%BF%9B%E5%85%A5%20prepared%22%5D%20--%3E%20W%5B%22%E5%8E%9F%E5%9C%B0%E7%AD%89%E5%BE%85%E5%86%B3%E7%AD%96%2C%20%E9%94%81%E4%B8%8D%E6%94%BE%22%5D%0A%20%20CR%5B%22%E5%8D%8F%E8%B0%83%E5%99%A8%E6%AD%A4%E5%88%BB%E5%AE%95%E6%9C%BA%22%5D%20--%3E%20REC%5B%22%E6%81%A2%E5%A4%8D%E5%90%8E%E5%85%88%E8%AF%BB%E5%8D%8F%E8%B0%83%E5%99%A8%E6%97%A5%E5%BF%97%22%5D%0A%20%20W%20--%3E%20REC%0A%20%20REC%20--%3E%20DEC%5B%22%E6%97%A5%E5%BF%97%E5%B7%B2%E5%86%99%20commit%2Fabort%20%E2%86%92%20%E9%80%9A%E7%9F%A5%E4%BC%97%E4%BA%BA%22%5D%0A%20%20REC%20--%3E%20UNK%5B%22%E5%86%B3%E7%AD%96%E6%9C%AA%E8%90%BD%E6%97%A5%E5%BF%97%20%E2%86%92%20%E5%8D%A1%E4%BD%8F%E6%88%96%E5%90%AF%E5%8F%91%E5%BC%8F%2C%20%E4%BA%BA%E5%B7%A5%E4%BB%8B%E5%85%A5%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">直觉类比：2PC 像婚礼司仪——先挨个问「愿意吗」，全员答愿意才宣布「礼成」，有一人说不愿就宣布散场。宣布一旦出口就是最终裁决；参与者必须<strong>听到</strong>裁决才能离场（放锁），听不到就只能站着等。</span></p><p><span class="marginnote">常见误区：以为 2PC 顺带保证了隔离。它只保证「一起提交或一起撤」；prepared 期间锁全都不放，节点内部的隔离仍靠各自的 2PL/MVCC——所以跨节点死锁与阻塞比单库更容易放大。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>2PC 不防恶意节点，也不保密。正确提交的事务仍可能被旁路读走、被伪造端点——这正是安全课要从 CIA 另起的缺口。也不处理网络分区下的可用性格：CAP 式放松（Paxos 提交、Saga）是后话，不插入本栏主干为「下一课」。</p><p>参与者在 prepared 时崩溃，重启必须仍记得「我已答应」，否则全局原子性裂开——这仍是 WAL，只是多一个决策位。后课默认：分布式原子可以做到；保密、完整、认证尚未成为对象。</p><p>协调器是新的单点：它的日志丢了，参与者会卡在 prepared。复制协调器是工程补丁，不是 2PC 规格的一部分。</p><p><span class="marginnote">术语翻译：「启发式窗口」= 协调器日志里找不到决策、参与者等到超时后<strong>自行猜测</strong>提交还是回滚的那段时间。两边猜的方向不一致，日志就对不上——这正是工程上要复制协调器的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>2PC 给崩溃故障下的原子，不给拜占庭、不给保密。</p></li><li><p>后课 CIA：提交正确仍可泄密或被冒充。</p></li><li><p>单库死锁已处理；跨 RM 原子靠 2PC 的投票与决策日志。</p></li><li><p>prepared 阻塞是协议的一部分；假设崩溃不是拜占庭。</p></li><li><p>提交正确仍可能泄密或被冒充，缺口交给 CIA。</p></li><li><p>出处：Gray；Lampson and Sturgis；Bernstein, Hadzilacos and Goodman。</p></li></ul>',9))])}const b=l(A,[["render",m]]);export{f as __pageData,b as default};
